solution.solution.py:
def run(schedule, start):
    counter = start
    register = {"A": 0, "B": 0}
    step = {"A": 0, "B": 0}
    for thread in schedule:
        if step[thread] == 0:
            register[thread] = counter
        elif step[thread] == 1:
            register[thread] += 1
        else:
            counter = register[thread]
        step[thread] = (step[thread] + 1) % 3
    return counter

unitTests:
@test("one after the other: no lost updates")
def _():
    check_eq(run("AAABBB", 0), 2)
    check_eq(run("BBBAAA", 10), 12)
    check_eq(run("AAAAAABBB", 0), 3)

@test("interleaved: an update is lost")
def _():
    check_eq(run("ABABAB", 0), 1)
    check_eq(run("AABBAB", 5), 6)

@test("an unfinished addition changes nothing yet")
def _():
    check_eq(run("AA", 0), 0)
    check_eq(run("", 7), 7)

